// ============================================================================
// RLE4K Code Parser
// ============================================================================
// Description: Parses 8-bit RLE4K encoded data into mode, color, and length
//              Based on RLE4K protocol specification
// Author: Generated by Claude Code
// Date: 2026-01-09
// ============================================================================

`timescale 1ns / 1ps

module rle4k_decoder_code_parser (
    input  wire        clk,
    input  wire        rst_n,

    // Input: 8-bit code from FIFO
    input  wire [7:0]  code_in,
    input  wire        code_valid_in,
    output wire        code_ready,

    // Output: Parsed parameters
    input  wire        parsed_ready,     // Ready signal from downstream (core)
    output reg         parsed_valid,
    output reg         code_color,       // 1=1b run, 0=0b run
    output reg  [11:0] code_length      // Unified length: 1-4032 bits (bit mode: 1-63, segment mode: 64-4032)
);

// ============================================================================
// RLE4K Protocol Encoding
// ============================================================================
// Bit Mode (bit7=0):
//   - 0x01-0x3F: 0b run, length = code[5:0] (1-63 bits)
//   - 0x41-0x7F: 1b run, length = code[5:0] (1-63 bits)
// Segment Mode (bit7=1):
//   - 0x81-0xBF: 0b run, block_count = code[5:0] (1-63 blocks, 64-4032 bits)
//   - 0xC1-0xFF: 1b run, block_count = code[5:0] (1-63 blocks, 64-4032 bits)
// Bytes with L=0 (e.g. 0x00, 0x40, 0x80, 0xC0) are decoded as MBL with length 0; core consumes them without boundary semantics.
// ============================================================================

// Internal signals
wire bit7  = code_in[7];  // Mode bit
wire bit6  = code_in[6];  // Color bit
wire [5:0] code_length_raw = code_in[5:0];

// Mode determination
wire is_bit_mode_wire  = ~bit7;      // bit7=0 -> bit mode; else segment mode

// Color determination
wire code_color_wire = bit6;         // bit6=1 -> 1b run, bit6=0 -> 0b run

// Unified length calculation
// Bit mode: code_length = code[5:0] (1-63 bits)
// Segment mode: code_length = code[5:0] * 64 (64-4032 bits)
wire [11:0] code_length_wire 
     = is_bit_mode_wire ? 
     {6'd0, code_length_raw} :
     {code_length_raw, 6'd0};  // Multiply by 64

// ============================================================================
// Parsing Logic with Ready/Valid Handshake
// ============================================================================
// code_ready is combinational on parsed_ready so a code can be accepted in the
// same cycle the previous one is handed downstream. The earlier version dropped
// code_ready for one cycle after every accept, which put a hard two-cycle floor
// under every code byte no matter how long a run it expanded to; that floor was
// the single largest implementation-side cost measured in
// reports/2026-08-09-e9-per-block-cycle-accounting.md.
assign code_ready = !parsed_valid || parsed_ready;

always @(posedge clk) begin
    if (!rst_n) begin
        parsed_valid    <= 1'b0;
        code_color      <= 1'b0;
        code_length     <= 12'd0;
    end else begin
        if (code_valid_in && code_ready) begin
            parsed_valid <= 1'b1;
            code_color   <= code_color_wire;
            code_length  <= code_length_wire;
        end else if (parsed_ready) begin
            parsed_valid <= 1'b0;
        end
    end
end

endmodule
